<script setup lang="ts">
import PageHeader from '../workspace/PageHeader.vue'
import {ref,computed,onMounted,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {LogOut,SlidersHorizontal,MonitorSmartphone,KeyRound} from 'lucide-vue-next'
import {useApp} from '../stores/app'
import {api,authGeneration} from '../api'
import {clearPrivate,native,backendBase,changeBackend,saveDeletionReceipt,accountId} from '../platform/bridge'
import {useRequestScope} from '../platform/request-scope'
import {completeAccountDeletion} from '../platform/account-deletion'
import Sheet from '../components/Sheet.vue'
import CharacterPreferences from '../components/CharacterPreferences.vue'
import PrivateBackup from '../components/PrivateBackup.vue'
import RecoverySettings from '../foundation/RecoverySettings.vue'
import {listVaults} from '../repositories/local-vault'
const hasLegacyDeviceData=ref(false)
onMounted(async()=>{const scope=capture();try{const vaults=await listVaults();if(scope.valid())hasLegacyDeviceData.value=vaults.length>0}catch{/* Account features do not depend on legacy device storage. */}})
const route=useRoute()
const section=ref(['security','reading','data'].includes(String(useRoute().query.section))?String(useRoute().query.section):'security'),allSessions=ref(false)
const visibleSessions=computed(()=>allSessions.value?sessions.value:[...sessions.value.filter(s=>s.current),...sessions.value.filter(s=>!s.current).slice(0,4)])
watch(()=>route.query.section,value=>{section.value=['security','reading','data'].includes(String(value))?String(value):'security'})
function selectSection(value:string){section.value=value;void router.push({path:'/settings',query:{...route.query,section:value}})}
const importingBackup=ref(false)
const store=useApp(),router=useRouter(),font=ref(store.settings.fontSize),line=ref(store.settings.lineHeight),theme=ref(store.settings.theme),error=ref(''),busy=ref(false),currentPassword=ref(''),newPassword=ref(''),deleting=ref(false),confirmation=ref(''),server=ref(backendBase()),sessions=ref<{id:string;clientType:string;deviceName:string;createdAt:string;current:boolean}[]>([])
const readingMode=ref(store.settings.readingMode||'scroll'),readingWidth=ref(store.settings.readingWidth||36),chapterLength=ref(store.settings.chapterLength||'standard')
const capture=useRequestScope();let requestGeneration=0,loadGeneration=0
async function load(){const scope=capture(),generation=++loadGeneration;try{const result=await api<{items:typeof sessions.value}>('/auth/sessions');if(scope.valid()&&generation===loadGeneration)sessions.value=result.items}catch(e){if(scope.valid()&&generation===loadGeneration)error.value=(e as Error).message}}
async function save(){const scope=capture(),generation=++requestGeneration,valid=()=>scope.valid()&&generation===requestGeneration;busy.value=true;error.value='';try{await store.saveSettings({version:store.settings.version,fontSize:font.value,lineHeight:line.value,theme:theme.value,readingMode:readingMode.value,readingWidth:readingWidth.value,chapterLength:chapterLength.value});if(valid())store.message('阅读设置已保存到账号')}catch(e){if(valid())error.value=(e as Error).message}finally{if(valid())busy.value=false}}
async function logout(){const scope=capture(),generation=++requestGeneration;try{const epoch=await store.logout();if(scope.valid(false)&&generation===requestGeneration&&epoch===authGeneration()&&!accountId())await router.push('/login')}catch(e){if(scope.valid())error.value=(e as Error).message}}
async function password(){const scope=capture(),generation=++requestGeneration,valid=()=>scope.valid()&&generation===requestGeneration;busy.value=true;try{await api('/auth/password',{method:'PUT',body:{currentPassword:currentPassword.value,newPassword:newPassword.value}});if(!valid())return;currentPassword.value='';newPassword.value='';await load();if(valid())store.message('密码已更新，其他设备已退出')}catch(e){if(valid())error.value=(e as Error).message}finally{if(valid())busy.value=false}}
async function revoke(id:string){const scope=capture();try{await api('/auth/sessions/'+id,{method:'DELETE'});if(scope.valid())await load()}catch(e){if(scope.valid())error.value=(e as Error).message}}
async function remove(){
  const scope=capture(),generation=++requestGeneration,base=backendBase(),valid=()=>scope.valid()&&generation===requestGeneration;busy.value=true
  try{
    store.exitingAccount=true
    const receipt=await api<{receiptId:string}>('/auth/delete-account',{method:'POST',body:{currentPassword:currentPassword.value,confirmation:confirmation.value}})
    const completion=completeAccountDeletion({id:receipt.receiptId,base},{native,saveReceipt:saveDeletionReceipt,clearPrivate,sameAccount:()=>scope.auth===authGeneration()&&scope.owner===accountId()&&base===backendBase()}),epoch=authGeneration()
    const {cleared,receiptStatus,cleanupFailed}=await completion;if(!cleared)return
    if(epoch!==authGeneration()||accountId())return
    if(scope.valid(false)&&generation===requestGeneration)await router.push('/login')
    if(epoch===authGeneration()&&!accountId())store.message(cleanupFailed?'账号已停用，部分本机清理未完成；服务端仍会继续清理':receiptStatus==='saved'?'账号已停用，私人数据清理任务已持久保存':receiptStatus==='local'?'账号已停用，清理回执已保存在本机；原生备份尚未确认':'账号已停用，本机清理回执保存失败；服务端仍会继续清理')
  }catch(e){if(valid()){store.exitingAccount=false;error.value=(e as Error).message}}finally{if(valid())busy.value=false}
}
async function configure(){const scope=capture(),generation=++requestGeneration;try{await changeBackend(server.value,()=>scope.valid()&&generation===requestGeneration);if(scope.valid(false)&&generation===requestGeneration&&!accountId())await router.push('/login')}catch(e){if(scope.valid())error.value=(e as Error).message}}
onMounted(load)
</script>
<template><div class="settings-layout"><PageHeader title="账号设置" description="管理个人资料、安全、阅读习惯和备份。"/><nav class="settings-sections" aria-label="设置分类"><button v-for="item in [{id:'security',name:'账号与安全'},{id:'reading',name:'阅读与角色'},{id:'data',name:'数据与备份'}]" :key="item.id" :aria-pressed="section===item.id" @click="selectSection(item.id)">{{item.name}}</button></nav><p v-if="error" class="error" role="alert">{{error}}</p><section v-if="section==='data'" class="setting-row"><h2>私人备份</h2><p class="muted">导入通过口令加密的备份；导出单个故事请到故事详情页。备份恢复到当前账号，原有故事和存档会保留。</p><button :disabled="!store.online" @click="importingBackup=true">导入私人备份</button></section><section v-if="section==='reading'" class="setting-row"><h2 class="row"><SlidersHorizontal :size="20"/>阅读显示</h2><label>字号 · {{font}} px<input v-model.number="font" type="range" min="14" max="32" step="1"></label><label>行距 · {{line}}<input v-model.number="line" type="range" min="1.4" max="2.2" step="0.1"></label><label>阅读方式<select v-model="readingMode" aria-label="阅读方式"><option value="scroll">滚动阅读</option><option value="slide">滑动翻页</option><option value="page">无动画翻页</option></select></label><label>正文宽度 · {{readingWidth}} 字<input v-model.number="readingWidth" type="range" min="32" max="40" step="1"></label><label>续写篇幅<select v-model="chapterLength" aria-label="续写篇幅"><option value="short">短章</option><option value="standard">标准</option><option value="long">长章</option></select></label><label>主题<select v-model="theme"><option value="light">明亮</option><option value="dark">夜间</option><option value="system">跟随系统</option></select></label><div class="hint" :style="{fontSize:font+'px',lineHeight:line,fontFamily:'SimSun,serif'}">雾港的灯还亮着。先把绳子收好，再听一个故事。</div><button class="primary" style="margin-top:16px" :disabled="busy||!store.online" @click="save">保存阅读设置</button></section><section v-if="section==='security'" class="setting-row"><h2>个人资料与权益</h2><p class="muted">管理个人资料、内测积分、会员和私人参考资料。</p><div class="product-actions"><RouterLink to="/product/account" class="inline-link">修改资料与头像</RouterLink><RouterLink to="/help" class="inline-link">使用帮助</RouterLink></div></section><section v-if="section==='security'" class="setting-row"><h2 class="row"><KeyRound :size="20"/>AI 模型</h2><p class="muted">内测模型已由平台准备，登录即可使用，无需填写密钥。</p><RouterLink to="/settings/models" class="inline-link">打开模型设置与使用记录</RouterLink></section><section v-if="section==='data'" class="setting-row"><h2>离线阅读</h2><RouterLink to="/downloads" class="inline-link">已下载的故事线</RouterLink></section><section v-if="section==='data'&&hasLegacyDeviceData" class="setting-row"><h2>旧版内容</h2><p class="muted">发现以前保存的内容，可以导入到我的作品，或导出完整备份。</p><RouterLink to="/settings/import-history" class="inline-link">导入旧版内容</RouterLink></section><CharacterPreferences v-if="section==='reading'"/><RecoverySettings v-if="section==='security'"/><section v-if="section==='security'" class="setting-row"><h2 class="row"><MonitorSmartphone :size="20"/>登录设备</h2><div v-for="s in visibleSessions" :key="s.id" class="list-item row between"><div>{{s.deviceName}} <span v-if="s.current" class="badge">当前设备</span><small class="muted" style="display:block">{{new Date(s.createdAt).toLocaleString('zh-CN')}}</small></div><button v-if="!s.current" @click="revoke(s.id)">撤销登录</button></div><p v-if="!sessions.length" class="muted">正在加载登录设备；读取失败时可重新打开此页面。</p><button v-if="sessions.length>5" @click="allSessions=!allSessions">{{allSessions?'收起设备列表':'查看全部 '+sessions.length+' 台设备'}}</button></section><section v-if="section==='security'" class="setting-row"><h2>修改密码</h2><form @submit.prevent="password"><label>当前密码<input v-model="currentPassword" type="password" autocomplete="current-password" required></label><label>新密码<input v-model="newPassword" type="password" autocomplete="new-password" required minlength="12" maxlength="128"></label><button :disabled="busy||!store.online">更新密码并退出其他设备</button></form></section><section v-if="native&&section==='security'" class="setting-row"><h2>后端服务器</h2><label>已允许的 HTTPS 服务<input v-model="server" type="url"></label><button @click="configure">切换服务器并退出当前账号</button></section><section v-if="section==='security'" class="setting-row settings-danger"><button @click="logout"><LogOut :size="18"/>退出登录</button><div class="divider"><h2>注销账号</h2><p class="muted">确认后立即停用账号，后台删除私人书籍、对话、Key 与文件。手工备份由部署者记录与清理。</p><button class="danger" :disabled="!store.online" @click="deleting=true;currentPassword=''">注销我的账号</button></div></section></div><Sheet v-if="importingBackup" title="导入私人备份" @close="importingBackup=false"><PrivateBackup mode="import"/></Sheet><Sheet v-if="deleting" title="确认注销账号" @close="deleting=false"><p>此操作会删除所有私人数据，无法撤销。</p><label>当前密码<input v-model="currentPassword" type="password" autocomplete="current-password"></label><label>输入“删除我的账号”<input v-model="confirmation"></label><p v-if="error" class="error">{{error}}</p><button class="danger" :disabled="busy||confirmation!=='删除我的账号'||!currentPassword" @click="remove">确认删除我的账号</button></Sheet></template>
